        '<bx-multi-select\n    [allSelectedTooltip]="args().allSelectedTooltip"\n    [allSelectedText]="args().allSelectedText"\n    [selectedCountText]="args().selectedCountText"\n    [summaryThreshold]="args().summaryThreshold"\n    [showSelectAll]="args().showSelectAll"\n    [selectAllLabel]="args().selectAllLabel"\n    [selectionScope]="args().selectionScope"\n    [selectAll]="args().selectAll"\n    [clearable]="args().clearable"\n    [clearLabel]="args().clearLabel"\n    [clearTooltip]="args().clearTooltip"\n    [selectionDisplay]="args().selectionDisplay"\n    [visibleTagCount]="args().visibleTagCount"\n    [tagOverflowText]="args().tagOverflowText"\n    [options]="args().options"\n    [isSearchable]="args().isSearchable"\n    [externalFiltering]="args().externalFiltering"\n    [searchValue]="args().searchValue"\n    [searchDebounce]="args().searchDebounce"\n    [searchPlaceholder]="args().searchPlaceholder"\n    [emptyMessage]="args().emptyMessage"\n    [loadingLabel]="args().loadingLabel"\n    [loadingAriaLabel]="args().loadingAriaLabel"\n    [hasMore]="args().hasMore"\n    [loadError]="args().loadError"\n    [panelClass]="args().panelClass"\n    [value]="args().value"\n    [id]="args().id"\n    [label]="args().label"\n    [placeholder]="args().placeholder"\n    [tooltip]="args().tooltip"\n    [hint]="args().hint"\n    [hintEnd]="args().hintEnd"\n    [error]="args().error"\n    [ariaLabel]="args().ariaLabel"\n    [ariaLabelledBy]="args().ariaLabelledBy"\n    [ariaDescribedBy]="args().ariaDescribedBy"\n    [dataTestId]="args().dataTestId"\n    [name]="args().name"\n    [invalid]="args().invalid"\n    [pending]="args().pending"\n    [touched]="args().touched"\n    [dirty]="args().dirty"\n    [disabled]="args().disabled"\n    [readonly]="args().readonly"\n    [readOnly]="args().readOnly"\n    [hidden]="args().hidden"\n    [required]="args().required"\n    [loading]="args().loading"\n    [submitted]="args().submitted"\n    [errorPolicy]="args().errorPolicy"\n    [errorMode]="args().errorMode"\n    [appearance]="args().appearance"\n    [floatLabel]="args().floatLabel"\n    [hideRequiredMarker]="args().hideRequiredMarker"\n    [subscriptSizing]="args().subscriptSizing"\n    [tooltipOnTruncate]="args().tooltipOnTruncate"\n    (selectionChange)="onAction(\'selectionChange\', $event)"\n    (selectAllIntentChange)="onAction(\'selectAllIntentChange\', $event)"\n    (search)="onAction(\'search\', $event)"\n    (loadMore)="onAction(\'loadMore\', $event)"\n    (openedChange)="onAction(\'openedChange\', $event)"\n    (touch)="onAction(\'touch\', $event)"\n    (selectAllChange)="onAction(\'selectAllChange\', $event)"\n    (searchValueChange)="onAction(\'searchValueChange\', $event)"\n    (valueChange)="onAction(\'valueChange\', $event)"\n    >{{ args().content }}</bx-multi-select\n>\n',
