        '<bx-bottom-drawer\n    [open]="args().open"\n    [offset]="args().offset"\n    [animationDuration]="args().animationDuration"\n    [modal]="args().modal"\n    [embedded]="args().embedded"\n    [dismissible]="args().dismissible"\n    [autoClose]="args().autoClose"\n    [closeOnBackdrop]="args().closeOnBackdrop"\n    [showBackdrop]="args().showBackdrop"\n    [showHandle]="args().showHandle"\n    [swipeToDismiss]="args().swipeToDismiss"\n    [showCloseButton]="args().showCloseButton"\n    [stickyFooter]="args().stickyFooter"\n    [autoFocus]="args().autoFocus"\n    [busy]="args().busy"\n    [disabled]="args().disabled"\n    [size]="args().size"\n    [maxHeight]="args().maxHeight"\n    [title]="args().title"\n    [subtitle]="args().subtitle"\n    [icon]="args().icon"\n    [ariaLabel]="args().ariaLabel"\n    [closeLabel]="args().closeLabel"\n    [headerVisible]="args().headerVisible"\n    [panelClass]="args().panelClass"\n    [panelStyle]="args().panelStyle"\n    [surfaceId]="args().surfaceId"\n    (closeRequest)="onAction(\'closeRequest\', $event)"\n    (closed)="onAction(\'closed\', $event)"\n    (closeCancelled)="onAction(\'closeCancelled\', $event)"\n    (openChange)="onAction(\'openChange\', $event)"\n    (offsetChange)="onAction(\'offsetChange\', $event)"\n    >{{ args().content }}</bx-bottom-drawer\n>\n',
      componentType: 'BottomDrawer',
